/// <summary>
/// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
/// Find method to find record from table METPurchGroup
/// </summary>
/// <param name = "_purchGroupId">purch group id</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>Table record</returns>
static METPurchGroup find(METPurchGroupId _purchGroupId, boolean _forUpdate = false)
{
    METPurchGroup    purchGroup;
    
    if (_purchGroupId)
    {
        purchGroup.selectForUpdate(_forUpdate);
      
        select firstonly purchGroup
                 where purchGroup.PurchGroupId == _purchGroupId;
    }
    
    return purchGroup;
}

/// <summary>
/// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
/// Exists method for table METPurchGroup.
/// </summary>
/// <param name = "_purchGroupId">purchgroupid</param>
/// <returns>check if exits</returns>
static boolean exist(METPurchGroupId _purchGroupId)
{
    return _purchGroupId  &&
           (select firstonly RecId from METPurchGroup
                 where METPurchGroup.PurchGroupId == _purchGroupId).RecId != 0;
}

/// <summary>
/// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
/// This method is used by the checkExist method.
/// </summary>
/// <returns>The value was not found</returns>
static public TxtNotExist txtNotExist()
{
    return "@MET:ValueNotFoundDefaultMsg";
}

    /// <summary>
    /// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
    /// CheckExist method for table METPurchGroup.
    /// </summary>
    /// <param name = "_purchGroupId">purchgroupid</param>
    /// <returns>check exists</returns>
    public static boolean checkExist(METPurchGroupId _purchGroupId)
    {
        boolean ret = true;
 
        if (!METPurchGroup::exist(_purchGroupId))
        {
            ret = checkFailed(strfmt(METPurchGroup::txtNotExist(),
                                 _purchGroupId,
                                 fieldId2PName(tableNum(METPurchGroup), fieldNum(METPurchGroup, PurchGroupId)),
                                 tableId2PName(tableNum(METPurchGroup))));
        }

        return ret;
    }
